#!/usr/bin/env bash
# Check GitHub releases for the ArtCraft apps listed in apps.conf and update
# them via locally stored PKGBUILDs + makepkg.
#
# Layout: $BUILD_ROOT/builds/<app>_PKGBUILD holds the generated templates; each
#         build runs in a temporary $BUILD_ROOT/builds/.build-<app>/ directory
#         that is removed afterwards.
#
# Usage:
#   ./update.sh                # check/update every app in apps.conf
#   ./update.sh photocraft     # only these apps
#   ./update.sh --force x      # rebuild even if the installed version matches
#   ./update.sh --dry-run      # build, but don't install (package kept in builds/)
#
# GITHUB_TOKEN is honored if set (raises the API rate limit).

set -uo pipefail

# Resolved from this script's location so the directory can be moved freely.
BUILD_ROOT="$(cd -- "$(dirname -- "${BASH_SOURCE[0]}")" && pwd)"
PKGBUILD_DIR="$BUILD_ROOT/builds"
APPS_CONF="$BUILD_ROOT/apps.conf"
ARCH_ASSET="linux-x86_64"
GITHUB_API="https://api.github.com"

FORCE=0
DRY=0
SELECTED=()

usage() {
	sed -n '2,14p' "$0" | sed 's/^# \{0,1\}//'
}

while (($#)); do
	case $1 in
	-f | --force) FORCE=1 ;;
	-n | --dry-run) DRY=1 ;;
	-h | --help) usage; exit 0 ;;
	-*) echo "unknown option: $1" >&2; usage >&2; exit 1 ;;
	*) SELECTED+=("$1") ;;
	esac
	shift
done

for tool in curl jq pacman makepkg vercmp sha256sum; do
	command -v "$tool" >/dev/null || { echo "missing dependency: $tool" >&2; exit 1; }
done
if ((EUID == 0)); then
	echo "do not run as root (makepkg refuses anyway)" >&2
	exit 1
fi
[[ -f $APPS_CONF ]] || { echo "no apps.conf at $APPS_CONF" >&2; exit 1; }
mkdir -p "$PKGBUILD_DIR"

# ---------------------------------------------------------------- helpers ---

log() { printf '%s\n' "$*"; }

gh() { # GET a GitHub API url
	if [[ -n ${GITHUB_TOKEN:-} ]]; then
		curl --compressed -fsSL \
			-H "Authorization: Bearer $GITHUB_TOKEN" \
			-H "X-GitHub-Api-Version: 2022-11-28" "$@"
	else
		curl --compressed -fsSL "$@"
	fi
}

strip_version() { # $1=tag $2=pkgname -> plain version
	local v=$1
	v=${v#"$2"-}
	v=${v#[vV]}
	printf '%s' "$v"
}

gen_pkgbuild() { # $1=name $2=repo $3=ver $4=tag $5=asset $6=url $7=sha256 $8=desc $9=depends_csv
	local name=$1 repo=$2 ver=$3 tag=$4 asset=$5 url=$6 sha=$7 desc=$8 depends_csv=$9

	desc=${desc//\"/}
	desc=${desc//\`/}
	desc=${desc//\$/}
	desc=${desc//$'\n'/ }
	[[ -n $desc ]] || desc="$name (ArtCraft application)"

	local depends="()"
	if [[ -n $depends_csv ]]; then
		local d items=() dlist=()
		IFS=',' read -ra dlist <<<"$depends_csv"
		for d in "${dlist[@]}"; do
			[[ -n $d ]] && items+=("'$d'")
		done
		depends="(${items[*]})"
	fi

	cat >"$PKGBUILD_DIR/${name}_PKGBUILD" <<EOF
# Maintainer: generated by update.sh (in the same directory) — do not edit by hand
# upstream release: $tag
pkgname=$name
pkgver=$ver
pkgrel=1
pkgdesc="$desc"
arch=('x86_64')
url="https://github.com/$repo"
license=('Apache-2.0' 'MIT')
depends=$depends
options=('!strip' '!debug')
source=("$asset::$url")
sha256sums=('$sha')

build() {
	:
}

package() {
	local top
	top=\$(find "\$srcdir" -mindepth 1 -maxdepth 1 -type d | head -n1)
	cd "\$top" || return 1

	local f
	for f in bin/*; do
		install -Dm755 "\$f" "\$pkgdir/usr/bin/\$(basename "\$f")"
	done

	install -d "\$pkgdir/usr/share"
	cp -a share/. "\$pkgdir/usr/share/"

	if ls share/doc/\$pkgname/LICENSE-* >/dev/null 2>&1; then
		install -d "\$pkgdir/usr/share/licenses/\$pkgname"
		cp -a share/doc/\$pkgname/LICENSE-* "\$pkgdir/usr/share/licenses/\$pkgname/"
	fi
}
EOF
}

# ----------------------------------------------------------- sudo keepalive ---

if ((DRY == 0)); then
	sudo -v || { echo "sudo authentication failed" >&2; exit 1; }
	while true; do
		sudo -n true
		sleep 50
	done 2>/dev/null &
	KEEPALIVE=$!
	trap 'kill $KEEPALIVE 2>/dev/null' EXIT
fi

# ------------------------------------------------------------------ updates ---

declare -a R_OK R_SKIP R_FAIL
FAILED=0

process_app() {
	local name=$1 repo=$2 extra=${3:-}
	local pkgbuild_file="$PKGBUILD_DIR/${name}_PKGBUILD"
	local builddir="$PKGBUILD_DIR/.build-$name"

	log ""
	log "=== $name ($repo) ==="

	# --- overrides (semicolon-separated: depends=a,b;asset=foo.tar.gz) ---
	local asset_ov="" depends_csv=""
	if [[ -n $extra ]]; then
		local pair pairs=()
		IFS=';' read -ra pairs <<<"$extra"
		for pair in "${pairs[@]}"; do
			[[ -z $pair ]] && continue
			case ${pair%%=*} in
			asset) asset_ov=${pair#*=} ;;
			depends) depends_csv=${pair#*=} ;;
			*) log "  warning: unknown override '$pair'" ;;
			esac
		done
	fi

	# --- latest release ---
	local rel tag
	if ! rel=$(gh "$GITHUB_API/repos/$repo/releases/latest"); then
		log "  ERROR: could not fetch latest release (no releases, rate limited, or repo missing)"
		R_FAIL+=("$name"); FAILED=1; return 0
	fi
	tag=$(jq -r '.tag_name // empty' <<<"$rel")
	if [[ -z $tag ]]; then
		log "  ERROR: latest release has no tag"
		R_FAIL+=("$name"); FAILED=1; return 0
	fi
	local ver
	ver=$(strip_version "$tag" "$name")
	log "  latest: $tag (version $ver)"

	# --- asset ---
	local asset sha url
	if [[ -n $asset_ov ]]; then
		asset=$asset_ov
		url=$(jq -r --arg a "$asset" '.assets[] | select(.name == $a) | .browser_download_url // empty' <<<"$rel" | head -n1)
	else
		url=$(jq -r --arg p "${name}-${ver}-${ARCH_ASSET}.tar.gz" \
			'.assets[] | select(.name == $p) | .browser_download_url' <<<"$rel" | head -n1)
		if [[ -z $url ]]; then # fall back to any main (non -cli-) linux x86_64 tarball
			url=$(jq -r --arg pre "${name}-" \
				'.assets[] | select(.name | startswith($pre))
				         | select(.name | endswith("-'"$ARCH_ASSET"'.tar.gz"))
				         | select(.name | contains("-cli-") | not)
				         | .browser_download_url' <<<"$rel" | head -n1)
		fi
		asset=${url##*/}
	fi
	if [[ -z $url || -z $asset ]]; then
		log "  SKIP: no ${ARCH_ASSET} tarball in release $tag"
		R_SKIP+=("$name (no asset)"); return 0
	fi
	log "  asset: $asset"

	sha=$(jq -r --arg a "$asset" \
		'.assets[] | select(.name == $a) | .digest // "" | sub("^sha256:"; "")' <<<"$rel")
	if [[ ! $sha =~ ^[0-9a-f]{64}$ ]]; then
		log "  no sha256 digest in API response, downloading to compute checksum..."
		mkdir -p "$builddir"
		if ! curl --compressed -fsSL -o "$builddir/$asset" "$url"; then
			log "  ERROR: download failed"
			rm -rf "$builddir"
			R_FAIL+=("$name"); FAILED=1; return 0
		fi
		sha=$(sha256sum "$builddir/$asset" | awk '{print $1}')
	fi

	# --- installed version ---
	local cmp=1 local_q
	if local_q=$(pacman -Q "$name" 2>/dev/null); then
		local inst=${local_q#* }
		inst=${inst%-*} # strip pkgrel
		cmp=$(vercmp "$ver" "$inst")
		log "  installed: $inst  vs  latest: $ver"
		if ((cmp == 0)) && ((FORCE == 0)); then
			log "  up to date"
			R_OK+=("$name (up to date)"); return 0
		fi
		if ((cmp < 0)) && ((FORCE == 0)); then
			log "  installed version is newer than the release — skipping (use --force to rebuild)"
			R_SKIP+=("$name (installed newer)"); return 0
		fi
	fi

	# --- repo description for pkgdesc ---
	local desc
	desc=$(gh "$GITHUB_API/repos/$repo" | jq -r '.description // empty') || desc=""

	# --- (re)generate the stored PKGBUILD template ---
	gen_pkgbuild "$name" "$repo" "$ver" "$tag" "$asset" "$url" "$sha" "$desc" "$depends_csv"
	log "  ${name}_PKGBUILD written (pkgver=$ver)"

	# --- build in a throwaway subdirectory ---
	rm -rf "$builddir"
	mkdir -p "$builddir"
	cp "$pkgbuild_file" "$builddir/PKGBUILD"

	local rc=0
	if ((DRY == 0)); then
		sudo -v || true
		log "  running makepkg -Cfis --noconfirm --needed --clean in $builddir ..."
		(cd "$builddir" && makepkg -Cfis --noconfirm --needed --clean) || rc=$?
	else
		log "  dry-run: building without installing ..."
		(cd "$builddir" && makepkg -Cf --noconfirm --clean) || rc=$?
	fi

	if ((rc == 0)); then
		if ((DRY)); then
			mv "$builddir"/*.pkg.tar.* "$PKGBUILD_DIR/" 2>/dev/null || true
			log "  built $name $ver-1 (dry-run, package kept in $PKGBUILD_DIR)"
			R_OK+=("$name -> $ver (dry-run)")
		else
			log "  installed $name $ver-1"
			R_OK+=("$name -> $ver")
		fi
	else
		log "  ERROR: makepkg failed for $name"
		R_FAIL+=("$name"); FAILED=1
	fi

	rm -rf "$builddir"
}

# -------------------------------------------------------------------- main ---

while IFS=$' \t' read -r name repo extra _ || [[ -n ${name:-} ]]; do
	[[ -z ${name:-} || $name == \#* ]] && continue
	if [[ -z ${repo:-} ]]; then
		log "malformed line in apps.conf: $name"
		continue
	fi
	if ((${#SELECTED[@]})); then
		skip=1
		for s in "${SELECTED[@]}"; do
			[[ $s == "$name" ]] && skip=0
		done
		((skip)) && continue
	fi
	process_app "$name" "$repo" "${extra:-}"
done <"$APPS_CONF"

log ""
log "================ summary ================"
for r in "${R_OK[@]:-}"; do [[ -n $r ]] && log "  ok      $r"; done
for r in "${R_SKIP[@]:-}"; do [[ -n $r ]] && log "  skipped $r"; done
for r in "${R_FAIL[@]:-}"; do [[ -n $r ]] && log "  FAILED  $r"; done
log "========================================="

exit $FAILED
